@RestController
@RequestMapping("/api/v1/users")
public class UserController {

    @GetMapping
    public ResponseEntity<MappingJacksonValue> getUsers(
            @RequestParam(required = false) String filter,
            @RequestParam(required = false) String sort,
            @RequestParam(name = "fields", required = false) String sparseFields) {

        List<User> users = userService.findWithFilterAndSort(filter, sort);

        SimpleBeanPropertyFilter propertyFilter = (sparseFields != null && !sparseFields.isEmpty())
            ? SimpleBeanPropertyFilter.filterOutAllExcept(sparseFields.split(","))
            : SimpleBeanPropertyFilter.serializeAll();

        FilterProvider filters = new SimpleFilterProvider()
            .addFilter("userFilter", propertyFilter);

        MappingJacksonValue mapping = new MappingJacksonValue(users);
        mapping.setFilters(filters);

        return ResponseEntity.ok(mapping);
    }
}
